import { unstable_cache } from 'next/cache'

export type Post = {
  id: string
  title: string
  createdAt: string
}

const posts: Post[] = []

export function addPost(title: string): Post {
  const post: Post = {
    id: crypto.randomUUID(),
    title,
    createdAt: new Date().toISOString(),
  }
  posts.push(post)
  return post
}

function readPosts(): Post[] {
  return posts.map((p) => ({ ...p }))
}

/** Tagged cache: invalidate with `updateTag('posts')` from a Server Action for immediate, fresh reads (no stale SWR). */
export const getCachedPosts = unstable_cache(
  async () => readPosts(),
  ['all-posts'],
  { tags: ['posts'] }
)

